typedef struct Loc {
    orbit_int line;
    orbit_int column;
} Loc;

#define Loc(...) (Loc*)orbit_model_Loc_create(arena, __VA_ARGS__)
static inline Loc* orbit_model_Loc_create(OrbitArena* a, orbit_int line, orbit_int column) {
    Loc* m = (Loc*)orbit_alloc(a, sizeof(Loc));
    m->line = line;
    m->column = column;
    return m;
}

typedef struct ParamNode {
    orbit_string name;
    orbit_string typeName;
} ParamNode;

#define ParamNode(...) (ParamNode*)orbit_model_ParamNode_create(arena, __VA_ARGS__)
static inline ParamNode* orbit_model_ParamNode_create(OrbitArena* a, orbit_string name, orbit_string typeName) {
    ParamNode* m = (ParamNode*)orbit_alloc(a, sizeof(ParamNode));
    m->name = name;
    m->typeName = typeName;
    return m;
}

